# Load all grids from the session
import os, re

def load_all_grids():
    d = os.environ.get('RLM_SESSION_DIR')
    if not d:
        return {}
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    # Parse labyrinth-style pattern
    lines = t.split('\n')
    i = 0
    for line in lines:
        line = line.strip()
        if not line or line.startswith('-'):
            continue
        # Look for pattern like "Demo pair X input (dxX):"
        match = re.match(r'(Demo pair \d+ (?:input|output)|Test input)\s*\((\d+)x(\d+)\):', line)
        if match:
            key, h, w = match.groups()
            rows = []
            for _ in range(int(h)):
                if i + 1 < len(lines):
                    rows.append(lines[i + 1].split())
                i += 1
            grid = [[int(x) for x in row] for row in rows]
            if key not in G:
                G[key] = grid
        i += 1
    return G

G = load_all_grids()
for k, v in G.items():
    print(f"{k}: {len(v)}x{len(v[0]) if v else 0}")
    if len(G[k]) <= 3:
        print(G[k])

import re
session_id = '01a18157-d531-767f-9bfc-8483d455939a'
sessions_dir = '/home/ubuntu/runs/paper/qwen-in-glm-hpl-u1-light/frozen/stream-100/play/users/u096/system/state/sessions'
filepath = os.path.join(sessions_dir, session_id + '.jsonl')

with open(filepath) as f:
    t = f.read()

# Find all Demo pairs using the correct regex
pattern = r'(Demo pair \d+ (?:input|output))\s*\((\d+)x(\d+)\):'
matches = list(re.finditer(pattern, t))
print(f"Found {len(matches)} matches")

# Group by demo name
G = {}
for i, m in enumerate(sorted(matches, key=lambda x: x.start())):
    full_key, h, w = m.groups()
    start = m.end()

    if i + 1 < len(matches):
        end = matches[i+1].start()
    else:
        end = len(t)

    col_text = t[start:end]

    # Parse rows
    rows = []
    lines = col_text.strip().split('\n')
    for line in lines:
        line = line.strip()
        if line and not line.startswith('(') and not line.startswith('{'):
            parts = line.split()
            if parts and all(x.isdigit() for x in parts):
                rows.append([[int(x) for x in parts]])
            else:
                rows.append([])

    if not G.get(full_key):
        G[full_key] = rows

    print(f"{full_key} ({h}x{w}): {len([r for r in rows if any(len(r)>0 for r in rows))]} rows")
    if full_key not in ['Demo pair 1 input (27x22):', 'Demo pair 1 output (27x22):']:
        print(f"  Sample: {rows[0][:2] if rows else None}")
    print()

